import{_ as t,o,c as e,ag as u}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第108章 两个文件夹","description":"","frontmatter":{},"headers":[],"relativePath":"第108章_两个文件夹.md","filePath":"第108章_两个文件夹.md"}'),_={name:"第108章_两个文件夹.md"};function a(q,p,r,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[u('<h1 id="第108章-两个文件夹" tabindex="-1">第108章 两个文件夹 <a class="header-anchor" href="#第108章-两个文件夹" aria-label="Permalink to &quot;第108章 两个文件夹&quot;">​</a></h1><p>我这辈子学会的第一个电脑操作，是&quot;存档&quot;。</p><p>那是高一的冬天，她教我的。</p><p>她那天在语音里说，她说你打完一把要先存档，你不存档，明天起来啥都没了。</p><p>我说，什么是存档。</p><p>她说，就是你把你现在这个样子留下。</p><p>她说，留下以后你哪天回来，你还是今天这个你。</p><p>我那年为了搞懂这个词，我特意把那个键按错了一次。</p><p>我按成了&quot;读取&quot;。</p><p>我那一局的进度全没了。</p><p>我在椅子上坐了很久，我不敢跟她说。</p><p>后来我跟她讲了。</p><p>她说，哈哈哈，你这个人。</p><p>她说，你以后打一把存一次。</p><p>我说，好。</p><p>她说，你别好，你要真的。</p><p>十一年以后，我在电脑前坐着，要给自己这十一年做一次存档。</p><p>那年我二十八。</p><p>她那边的生意停了半年。</p><p>不是因为吵架。</p><p>是因为她那边有一个孩子出生了，她把重心挪去另一边。</p><p>我们两个两个月没有结过一次账。</p><p>那两个月里我没有一件事可干。</p><p>我有一天下午，把家里那台旧笔记本抱出来。</p><p>我要把它换掉。</p><p>换之前我要把里面的东西倒出来。</p><p>我坐在那儿，从上午十点开始。</p><p>我里面存的东西是这样的：</p><p>一个文件夹，里面全是压缩包。</p><p>每一个压缩包是一个月。</p><p>文件名是 2019_03 这样。</p><p>一共 143 个。</p><p>我算过，143 个月。</p><p>十二年。</p><p>我从第一个开始点，点到第九个，我停了。</p><p>我停下来的原因是：我那时候还不知道我在干什么。</p><p>我以为我是在整理。</p><p>其实我是在挑。</p><p>我要挑出哪些留下，哪些不留下。</p><p>而挑这个动作，需要一把尺。</p><p>我那把尺是这样的：这一条如果她哪天问起，我拿不拿得出来。</p><p>拿得出来我就留。</p><p>拿不出来我就删。</p><p>也就是说，我这十一年存的所有东西，我全部按&quot;她会不会问&quot;来分。</p><p>那天上午我坐在电脑前面很久。</p><p>我最后决定不做这个分法。</p><p>我重新建了一个文件夹。</p><p>我在里面建了两个子文件夹。</p><p>我打算这样分：</p><p>一个里面放她讲过的。</p><p>一个里面放我讲过的。</p><p>我建完发现一件事。</p><p>第一个我起不了名。</p><p>第二个我也起不了名。</p><p>我那天下午起来过四次。</p><p>第一次我写&quot;她&quot;。</p><p>第二次我写&quot;程&quot;。</p><p>第三次我写&quot;那边&quot;。</p><p>第四次我写&quot;空椅&quot;。</p><p>那是她的账号名。</p><p>我看了一眼，我把&quot;空椅&quot;删了。</p><p>因为那是台面上的名字。</p><p>我这十一年里，她有两个名字。</p><p>一个是明面上的。</p><p>一个是只给我的。</p><p>我要是拿明面上那个命名这个文件夹，我就等于在她自己都不认的地方，替她认了一次。</p><p>最后我起的是这个：</p><p>第一个子文件夹，我叫它&quot;存档&quot;。</p><p>第二个，我留着没起名。</p><p>我那个没起名的子文件夹，那年十一月是空的。</p><p>空的有 3.4 个 G。</p><p>它为什么这么大？</p><p>因为里面什么都没有。</p><p>我那天盯着那个&quot;3.4G&quot;看了很久。</p><p>后来我才想明白它是什么。</p><p>那里面装的不是文件。</p><p>那里面装的是我要往里放、但我一次也没放进去的东西。</p><p>我这十一年跟她讲过所有的话，我全存在&quot;存档&quot;那一个里。</p><p>那一个 3.4 的空文件夹，是我这十一年没讲出来的。</p><p>那天晚上十一点，我上线给她发了一句。</p><p>我说，我今天在整理电脑。</p><p>她说，整理出什么了。</p><p>我说，我建了两个文件夹。</p><p>她说，然后呢。</p><p>我说，一个我起好了名。</p><p>她说，另一个呢。</p><p>我说，另一个我不知道叫什么。</p><p>她隔了一会儿。</p><p>她说，你先别叫。</p><p>我说，为什么。</p><p>她说，因为一个东西你叫不出名字，说明它现在还不是一个东西。</p><p>她说，它是一个还没有发生的事。</p><p>她说，你把它先空着。</p><p>她说，你空着，它早晚有一天会自己长出名字。</p><p>我说，那要是它一直空着呢。</p><p>她说，那它就是没有。</p><p>她说，没有的东西不需要名字。</p><p>她说，你这十一年给我写了那么多，你今天告诉我你有一个文件夹是空的。</p><p>我说，对。</p><p>她说，那个空的里面有没有今天的这个。</p><p>我说，有。</p><p>她说，那你明天给它起个名。</p><p>我说，你不是说先别叫。</p><p>她说，我改主意了。</p><p>她说，你今天既然跟我讲了，那它就不是空的。</p><p>她说，你明天要还叫不出来，你就把我这个名字写进去。</p><p>我说，你哪个名字。</p><p>她说，你知道我讲哪个。</p><p>那天夜里我关了电脑。</p><p>我关之前，我把那两个子文件夹并排放好。</p><p>一个&quot;存档&quot;，41G。</p><p>一个空，3.4G。</p><p>那四十一个 G 我存了三份。</p><p>第一份在硬盘。</p><p>第二份在一个网上盘。</p><p>第三份在一张我专门买的光盘上。</p><p>那张盘我一年刻一次，刻完我拿记号笔在上面写一个年份，写完我放进一个铁盒。</p><p>我买那张盘花了八块。</p><p>那天下午我拿着那张盘坐了很久。</p><p>因为我发现了一件事。</p><p>我这十一年把一个人存了三个地方。</p><p>我存到了硬盘、盘、和一个能拿在手里的塑料片上。</p><p>我没有一天把她存在一个活人的面前。</p><p>我没跟我妈讲过。</p><p>我没跟陈树讲过全部。</p><p>我没跟任何人讲过那十一天里哪一句是她哪天中午说的。</p><p>我这十一年里唯一看过这些字的人，是我自己。</p><p>而我自己今天才开始看。</p><p>那天我把那张盘放进铁盒。</p><p>我盖盖子那一下，我听见盒子里已经有三张在响。</p><p>我那年二十六。</p><p>前面三年，三年一年一张。</p><p>我把那张盘压在最底下。</p><p>压完我想，我这一辈子对&quot;丢&quot;这个东西怕到骨头里。</p><p>我怕硬盘坏，我怕手机被收，我怕搬家丢，我怕人跑。</p><p>我把全部力气花在让东西不丢。</p><p>我没花过一分钟在想：今天这句我要当面对她讲。</p><p>我看着那个铁盒坐了很久。</p><p>那个盒子很小。</p><p>它现在里面是四张盘。</p><p>到今年为止是五张。</p><p>我看着那 41 和 3.4 坐了一会儿。</p><p>我这十一年，说出来的有 41 个 G。</p><p>没说出来的，占 3.4 个 G。</p><p>那天我以为没说的那一部分小得多。</p>',145)])])}const l=t(_,[["render",a]]);export{d as __pageData,l as default};
